// ❌ Anti-patrón: lógica de daño dentro de MonoBehaviour
public class EnemyBad : MonoBehaviour
{
    public int health = 100;
    public int armor = 20;

    // Esta lógica NO necesita MonoBehaviour
    public int CalculateDamage(int rawDamage, bool isCritical)
    {
        float multiplier = isCritical ? 2.0f : 1.0f;
        return Mathf.Max(0, (int)(rawDamage * multiplier) - armor);
    }
}

// ✅ Patrón correcto: lógica en POCO + MonoBehaviour como fachada
public class DamageCalculator   // POCO puro
{
    public int armor;
    public DamageCalculator(int armor) { this.armor = armor; }

    public int Calculate(int rawDamage, bool isCritical)
    {
        float multiplier = isCritical ? 2.0f : 1.0f;
        return Mathf.Max(0, (int)(rawDamage * multiplier) - armor);
    }
}

public class Enemy : MonoBehaviour   // Solo coordinación Unity
{
    public int health = 100;
    private DamageCalculator _calc = new DamageCalculator(20);

    public void TakeDamage(int raw, bool crit)
    {
        health -= _calc.Calculate(raw, crit);
    }
}

