public class DamageFormula
{
    private int _baseDamage;
    public DamageFormula(int base) { _baseDamage = base; }
    public int Apply(float multiplier) => (int)(_baseDamage * multiplier);
}

public class WeaponHandler : MonoBehaviour
{
    [SerializeField] private int _baseDamage = 25;
    [SerializeField] private float _critChance = 0.15f;

    public int Fire(bool isCrit)
    {
        float mult = isCrit ? 2.5f : 1.0f;
        return (int)(_baseDamage * mult);
    }
}

public class Inventory
{
    private List<Item> _items = new List<Item>();

    public void Add(Item item) => _items.Add(item);
    public bool Remove(Item item) => _items.Remove(item);
    public int Count => _items.Count;
}

public class EnemyAI : MonoBehaviour
{
    public float health = 100f;
    public float armor = 15f;

    // Calcula daño final considerando armadura y resistencias
    public float ComputeFinalDamage(float raw, float piercing)
    {
        float effective = Mathf.Max(0f, armor - piercing);
        return Mathf.Max(1f, raw - effective);
    }

    void Update() { /* mover al objetivo */ }
}

